mapper.insert:
insert into test_session (
    member_id, test_session_type, num_of_question, started_date
) values (
    #{memberId}, #{testSessionType}, #{numOfQuestion}, now()
)

insert into test_session_detail (
    test_session_id, sign_word_id, question_no, user_answer, is_correct, answer_date
) values (
    #{testSessionId}, #{signWordId}, #{questionNo}, #{userAnswer}, #{isCorrect}, now()
)
